"""`.Parse nipple textures`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Parse nipple textures'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Color', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('INPUT', 'skin tex', 'NodeSocketColor')
    t.socket('INPUT', 'nip tex', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Nipple alpha', 'NodeSocketFloat', subtype='FACTOR', default_value=0.5, min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Nipple 1', 'NodeSocketColor', default_value=(0.8549927, 0.5028865, 0.48514998, 1.0))
    t.socket('INPUT', 'Nipple 2', 'NodeSocketColor', default_value=(0.65837497, 0.09321279, 0.074091025, 1.0))
    t.socket('INPUT', 'Nipple 3', 'NodeSocketColor', default_value=(0.8631572, 0.7313192, 0.7251629, 1.0))
    t.socket('INPUT', 'Nipple 4', 'NodeSocketColor', default_value=(0.9559734, 0.9559734, 0.9559734, 1.0))

    t.node('ShaderNodeValToRGB', 'ColorRamp.002', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, color_ramp={'color_mode': 'RGB', 'interpolation': 'LINEAR', 'hue_interpolation': 'NEAR', 'elements': [{'position': 0.0, 'color': (0.0, 0.0, 0.0, 1.0)}, {'position': 1.0, 'color': (1.0, 1.0, 1.0, 1.0)}]}, props={
        'location': (-742.8905, -220.55347),
    })
    t.node('ShaderNodeMix', 'Mix.008', inputs={'Factor_Float': 0.5, 'A_Color': (0.0, 0.0, 0.0, 1.0), 'B_Color': (0.8549927, 0.5028865, 0.48514998, 1.0)}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (4.8513184, -184.20331),
        'data_type': 'RGBA',
    })
    t.node('ShaderNodeMix', 'Mix.001', outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (252.31595, 22.012054),
        'data_type': 'RGBA',
        'blend_type': 'SUBTRACT',
    })
    t.node('ShaderNodeMix', 'Mix.009', inputs={'Factor_Float': 0.5, 'A_Color': (0.030872855, 0.030872855, 0.030872855, 1.0), 'B_Color': (0.65837497, 0.09321279, 0.074091025, 1.0)}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (495.1409, 33.17694),
        'data_type': 'RGBA',
    })
    t.node('ShaderNodeMix', 'Mix.007', inputs={'Factor_Float': 0.5, 'B_Color': (0.8631572, 0.7313192, 0.7251629, 1.0)}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (708.18945, 220.55347),
        'data_type': 'RGBA',
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (1118.1895, 0.0),
    })
    t.node('ShaderNodeMix', 'Mix.010', inputs={'Factor_Float': 0.5, 'B_Color': (0.9559734, 0.9559734, 0.9559734, 1.0)}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (928.18945, 73.2807),
        'data_type': 'RGBA',
    })
    t.node('ShaderNodeSeparateColor', 'Separate RGB.001', props={
        'location': (-154.55684, 153.82999),
    })
    t.node('ShaderNodeMix', 'Mix.006', outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (-431.63574, 94.154785),
        'data_type': 'RGBA',
        'blend_type': 'MULTIPLY',
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-947.6122, -17.011011),
    })

    t.link('Group Input', 'Nipple alpha', 'ColorRamp.002', 'Fac')
    t.link('Group Input', 'skin tex', 'Mix.008', 'A_Color')
    t.link('Mix.010', 'Result_Color', 'Group Output', 'Color')
    t.link('Group Input', 'Nipple 1', 'Mix.008', 'B_Color')
    t.link('Group Input', 'Nipple 2', 'Mix.009', 'B_Color')
    t.link('Group Input', 'Nipple 3', 'Mix.007', 'B_Color')
    t.link('Group Input', 'Nipple 4', 'Mix.010', 'B_Color')
    t.link('Mix.006', 'Result_Color', 'Separate RGB.001', 'Color')
    t.link('ColorRamp.002', 'Color', 'Mix.006', 'B_Color')
    t.link('ColorRamp.002', 'Color', 'Mix.008', 'Factor_Float')
    t.link('Mix.001', 'Result_Color', 'Mix.009', 'Factor_Float')
    t.link('ColorRamp.002', 'Color', 'Mix.001', 'A_Color')
    t.link('Separate RGB.001', 'Red', 'Mix.001', 'B_Color')
    t.link('Mix.008', 'Result_Color', 'Mix.009', 'A_Color')
    t.link('Separate RGB.001', 'Green', 'Mix.007', 'Factor_Float')
    t.link('Mix.009', 'Result_Color', 'Mix.007', 'A_Color')
    t.link('Mix.007', 'Result_Color', 'Mix.010', 'A_Color')
    t.link('Separate RGB.001', 'Blue', 'Mix.010', 'Factor_Float')
    t.link('Group Input', 'nip tex', 'Mix.006', 'A_Color')
    return t
